create table xxcus.xxfnd_retention_policies (
    retention_policy_id   number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    table_name            varchar2(128 byte) not null enable,
    jurisdiction          varchar2(30 byte),
    retention_years       number(3, 0) not null enable,
    action_at_expiry      varchar2(30 byte) not null enable,
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_retention_policies
    add constraint xxfnd_retention_policies_ck1
        check ( action_at_expiry in ( 'ARCHIVE', 'PURGE', 'FLAG_FOR_REVIEW' ) ) enable;

alter table xxcus.xxfnd_retention_policies add constraint xxfnd_retention_policies_ck2 check ( retention_years > 0 ) enable;

alter table xxcus.xxfnd_retention_policies
    add constraint xxfnd_retention_policies_ck3
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_retention_policies
    add constraint xxfnd_retention_policies_pk primary key ( retention_policy_id )
        using index enable;


